#include <bits/stdc++.h>
using namespace std;

struct InputReader {
    virtual string next() = 0;
    virtual int nextInt() = 0;
    virtual ~InputReader() {}
};

struct ScannerInputReader : public InputReader {
    istream& in;
    ScannerInputReader(istream& input) : in(input) {}
    string next() override {
        string s;
        in >> s;
        return s;
    }
    int nextInt() override {
        int x;
        in >> x;
        return x;
    }
};

struct NumberTheory {
    struct Mod998 {
        static const long long MOD = 998244353LL;
        long long fact[2000001], invFact[2000001];

        Mod998() {
            fact[0] = 1;
            for (int i = 1; i <= 2000000; i++) {
                fact[i] = (fact[i - 1] * i) % MOD;
            }
            invFact[2000000] = modInverse(fact[2000000], MOD);
            for (int i = 2000000 - 1; i >= 0; i--) {
                invFact[i] = (invFact[i + 1] * (i + 1)) % MOD;
            }
        }

        long long modInverse(long long a, long long m) {
            return powMod(a, m - 2, m);
        }

        long long powMod(long long base, long long exp, long long mod) {
            long long result = 1;
            long long cur = base % mod;
            while (exp > 0) {
                if (exp & 1) result = (result * cur) % mod;
                cur = (cur * cur) % mod;
                exp >>= 1;
            }
            return result;
        }

        long long add(long long a, long long b) {
            long long res = a + b;
            if (res >= MOD) res -= MOD;
            return res;
        }

        long long subtract(long long a, long long b) {
            long long res = a - b;
            if (res < 0) res += MOD;
            return res;
        }

        long long mult(long long a, long long b) {
            return (a * b) % MOD;
        }

        long long ncr(int n, int r) {
            if (r < 0 || r > n) return 0;
            return fact[n] * invFact[r] % MOD * invFact[n - r] % MOD;
        }

        long long smallInv(long long a) {
            return modInverse(a, MOD);
        }
    };
};

struct HZSShufflesCards {
    NumberTheory::Mod998 mod;
    int n, m;

    void solve(int testNumber, InputReader& in, ostream& out) {
        n = in.nextInt();
        m = in.nextInt();

        // precompute inverse of n + m
        long long invNPlusM = mod.smallInv(n + m);

        long long phaseSize = 1;
        long long p = 1;
        for (int i = 0; p != 0; i++) {
            p = (p * (n - i)) % mod.MOD;
            p = (p * mod.smallInv(n + m - i)) % mod;
            phaseSize = (phaseSize + p) % mod.MOD;
        }

        long long answer = 0;
        for (int k = 1; k <= n; k++) {
            long long numPhases = (long long)(m + k) * mod.smallInv(k) % mod.MOD;
            long long term = mod.ncr(n, k);
            term = (term * numPhases) % mod.MOD;
            term = (term * phaseSize) % mod.MOD;
            if (k % 2 == 1) {
                answer = (answer + term) % mod.MOD;
            } else {
                answer = (answer - term + mod.MOD) % mod.MOD;
            }
        }

        out << answer << "\n";
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ScannerInputReader in(cin);
    HZSShufflesCards solver;
    solver.solve(1, in, cout);
    return 0;
}

